import{_ as n,C as r,c as o,o as l,a9 as s,G as t}from"./chunks/framework.DuenUNqn.js";const b=JSON.parse('{"title":"开始","description":"","frontmatter":{"breadcrumbs":[{"title":"Continue Project","link":"/wiki"},{"title":"Terra","link":"/wiki/Terra"},{"title":"getting-started","link":"/wiki/Terra/getting-started"}]},"headers":[],"relativePath":"wiki/Terra/getting-started/index.md","filePath":"wiki/Terra/getting-started/index.md"}'),f={name:"wiki/Terra/getting-started/index.md"};function c(p,e,g,h,u,k){const a=r("NolebaseGitContributors"),i=r("NolebaseGitChangelog");return l(),o("div",null,[e[0]||(e[0]=s('<h1 id="开始" tabindex="-1">开始 <a class="header-anchor" href="#开始" aria-label="Permalink to &quot;开始&quot;">​</a></h1><p>Terra 的全平台 API 允许我们无感支持许多类型的 Minecraft 模组平台。目前支持的模组加载器包括 <a href="https://fabricmc.net/" target="_blank" rel="noreferrer">Fabric</a>、<a href="https://files.minecraftforge.net/" target="_blank" rel="noreferrer">Forge</a>、<a href="https://quiltmc.org/" target="_blank" rel="noreferrer">Quilt</a> 以及 Bukkit 生态。对于 <a href="https://dev.bukkit.org/" target="_blank" rel="noreferrer">Bukkit</a>，我们还推出了支持 <a href="https://papermc.io/" target="_blank" rel="noreferrer">Paper</a>+ 的版本，支持包括但不限于 <a href="https://github.com/pufferfish-gg/Pufferfish" target="_blank" rel="noreferrer">Pufferfish</a> 及 <a href="https://purpurmc.org/" target="_blank" rel="noreferrer">Purpur</a> 的核心。</p><ul><li><p><a href="./fabric-installation">Fabric 服务器及客户端 &gt;</a> Fabric 为 Terra 最初开发的平台。如果你只是在单人游戏或与好友一起玩的小型服务器中使用，则建议选择 Fabric。</p></li><li><p><a href="./quilt-installation">Quilt 服务器及客户端 &gt;</a> 如果你只是在单人游戏或与好友一起玩的小型服务器中使用，则建议选择 Quilt。</p></li><li><p><a href="./forge-installation">Forge 服务器及客户端 &gt;</a> 如果你只是在单人游戏或与好友一起玩的小型服务器中使用，则建议选择 Forge。但如果你只需要使用 Terra，则建议你使用 Fabric。</p></li><li><p><a href="./bukkit-installation/">Bukkit 服务器 &gt;</a> 推荐人数较多规模较大的服务器使用。你可能更喜欢使用 Bukkit，因为大型服务器总是会用到许多插件。小型服务器不建议使用 Bukkit，若要在这种情况下使用 Terra，则建议选择 Fabric。</p></li></ul><h2 id="所有现存与往期发行版" tabindex="-1">所有现存与往期发行版 <a class="header-anchor" href="#所有现存与往期发行版" aria-label="Permalink to &quot;所有现存与往期发行版&quot;">​</a></h2><p>想要知晓 Terra 是否支持你的 Minecraft？你可以在<a href="./versions">这里</a>找到受支持、不受支持以及旧版本的 Terra 列表。</p>',5)),t(a),t(i)])}const d=n(f,[["render",c]]);export{b as __pageData,d as default};
